CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (user_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), full_name VARCHAR(150) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, phone VARCHAR(20), password_hash VARCHAR(255) NOT NULL, role VARCHAR(30) NOT NULL CHECK(role IN ('CITIZEN','FIELD_WORKER','OFFICER','ADMIN')), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS departments (department_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name VARCHAR(100) NOT NULL UNIQUE, description TEXT, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS categories (category_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name VARCHAR(100) NOT NULL UNIQUE, department_id UUID NOT NULL REFERENCES departments(department_id), default_sla_hours INT NOT NULL DEFAULT 48, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS complaints (complaint_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), citizen_id UUID NOT NULL REFERENCES users(user_id), department_id UUID REFERENCES departments(department_id), category_id UUID NOT NULL REFERENCES categories(category_id), title VARCHAR(200) NOT NULL, description TEXT NOT NULL, latitude DOUBLE PRECISION, longitude DOUBLE PRECISION, address TEXT, priority VARCHAR(20) NOT NULL DEFAULT 'MEDIUM', status VARCHAR(30) NOT NULL DEFAULT 'REPORTED', due_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_complaint_status ON complaints(status); CREATE INDEX IF NOT EXISTS idx_complaint_location ON complaints(latitude,longitude);
CREATE TABLE IF NOT EXISTS complaint_media (media_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), complaint_id UUID NOT NULL REFERENCES complaints(complaint_id) ON DELETE CASCADE, media_type VARCHAR(20) NOT NULL, file_url TEXT NOT NULL, uploaded_by UUID NOT NULL REFERENCES users(user_id), uploaded_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS assignments (assignment_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), complaint_id UUID NOT NULL UNIQUE REFERENCES complaints(complaint_id) ON DELETE CASCADE, worker_id UUID NOT NULL REFERENCES users(user_id), assigned_by UUID NOT NULL REFERENCES users(user_id), assigned_at TIMESTAMPTZ NOT NULL DEFAULT now(), accepted_at TIMESTAMPTZ, completed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS status_history (history_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), complaint_id UUID NOT NULL REFERENCES complaints(complaint_id) ON DELETE CASCADE, old_status VARCHAR(30), new_status VARCHAR(30) NOT NULL, changed_by UUID NOT NULL REFERENCES users(user_id), remarks TEXT, changed_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS notifications (notification_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(user_id) ON DELETE CASCADE, complaint_id UUID REFERENCES complaints(complaint_id) ON DELETE CASCADE, title VARCHAR(200) NOT NULL, message TEXT NOT NULL, read_status BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS resolution_verifications (verification_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), complaint_id UUID NOT NULL REFERENCES complaints(complaint_id) ON DELETE CASCADE, citizen_id UUID NOT NULL REFERENCES users(user_id), result VARCHAR(30) NOT NULL, comment TEXT, verified_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS duplicate_candidates (candidate_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), complaint_id UUID NOT NULL REFERENCES complaints(complaint_id) ON DELETE CASCADE, related_complaint_id UUID NOT NULL REFERENCES complaints(complaint_id) ON DELETE CASCADE, similarity_score NUMERIC(5,4) NOT NULL, decision VARCHAR(30) DEFAULT 'PENDING', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs (audit_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID REFERENCES users(user_id), action VARCHAR(100) NOT NULL, entity_type VARCHAR(50), entity_id UUID, ip_address VARCHAR(45), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
